-- Contract schema; future SQLite adapter must enable foreign_keys, WAL and busy_timeout.
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, checksum TEXT NOT NULL UNIQUE, applied_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, normalized_email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('operator','deployer')), status TEXT NOT NULL CHECK(status IN ('active','suspended','revoked')), created_at TEXT NOT NULL);
CREATE TABLE identities (id TEXT PRIMARY KEY, normalized_email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, last_authenticated_at TEXT);
CREATE TABLE api_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), app_id TEXT REFERENCES applications(id), secret_hash BLOB NOT NULL UNIQUE, scopes TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, last_used_at TEXT);
CREATE TABLE applications (id TEXT PRIMARY KEY, owner_user_id TEXT NOT NULL REFERENCES users(id), slug TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('creating','active','suspended','deleting','deleted','failed')), current_deployment_id TEXT, policy_revision INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE access_policies (app_id TEXT NOT NULL REFERENCES applications(id), revision INTEGER NOT NULL, mode TEXT NOT NULL CHECK(mode='private'), created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL, PRIMARY KEY(app_id,revision));
CREATE TABLE access_rules (id TEXT PRIMARY KEY, app_id TEXT NOT NULL, policy_revision INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('owner','email','domain')), normalized_value TEXT NOT NULL, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(app_id,policy_revision,kind,normalized_value), FOREIGN KEY(app_id,policy_revision) REFERENCES access_policies(app_id,revision));
CREATE TABLE otp_challenges (id TEXT PRIMARY KEY, app_id TEXT REFERENCES applications(id), purpose TEXT NOT NULL CHECK(purpose IN ('viewer','control')), normalized_email TEXT NOT NULL, code_hash BLOB NOT NULL, expires_at TEXT NOT NULL, attempts INTEGER NOT NULL CHECK(attempts>=0), consumed_at TEXT, invalidated_at TEXT, request_fingerprint_hash BLOB, created_at TEXT NOT NULL, CHECK((purpose='viewer' AND app_id IS NOT NULL) OR (purpose='control' AND app_id IS NULL)), UNIQUE(app_id,normalized_email,id));
CREATE TABLE sessions (id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('control','app')), app_id TEXT REFERENCES applications(id), identity_id TEXT REFERENCES identities(id), user_id TEXT REFERENCES users(id), secret_hash BLOB NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, last_seen_at TEXT, created_at TEXT NOT NULL, CHECK((scope='app' AND app_id IS NOT NULL AND identity_id IS NOT NULL AND user_id IS NULL) OR (scope='control' AND user_id IS NOT NULL AND app_id IS NULL AND identity_id IS NULL)));
CREATE TABLE deployments (id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES applications(id), created_by TEXT REFERENCES users(id), idempotency_key TEXT, archive_hash TEXT, release_hash TEXT, state TEXT NOT NULL CHECK(state IN ('uploading','uploaded','validating','staged','verified','active','superseded','rejected','failed')), failure_code TEXT, manifest_json TEXT, created_at TEXT NOT NULL, verified_at TEXT, activated_at TEXT, UNIQUE(app_id,idempotency_key));
CREATE TABLE deployment_files (deployment_id TEXT NOT NULL REFERENCES deployments(id), relative_path TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0), content_hash TEXT NOT NULL, media_type TEXT, PRIMARY KEY(deployment_id,relative_path));
CREATE TABLE app_kv (app_id TEXT NOT NULL REFERENCES applications(id), key TEXT NOT NULL, value_json BLOB NOT NULL, version INTEGER NOT NULL CHECK(version>0), size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(app_id,key));
CREATE TABLE app_quota_usage (app_id TEXT NOT NULL REFERENCES applications(id), metric TEXT NOT NULL, used INTEGER NOT NULL CHECK(used>=0), limit_value INTEGER NOT NULL CHECK(limit_value>=0), measured_at TEXT NOT NULL, PRIMARY KEY(app_id,metric));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, occurred_at TEXT NOT NULL, actor_kind TEXT NOT NULL, actor_id TEXT, app_id TEXT REFERENCES applications(id), action TEXT NOT NULL, outcome TEXT NOT NULL, target_kind TEXT, target_id TEXT, request_id TEXT, metadata_json TEXT);
CREATE TABLE outbox (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload_encrypted_or_redacted BLOB NOT NULL, available_at TEXT NOT NULL, attempts INTEGER NOT NULL CHECK(attempts>=0), state TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, scope_id TEXT, state TEXT NOT NULL, lease_until TEXT, attempts INTEGER NOT NULL CHECK(attempts>=0), last_error_code TEXT);
CREATE INDEX idx_sessions_app_secret ON sessions(app_id,secret_hash);
CREATE INDEX idx_deployments_app_created ON deployments(app_id,created_at);
CREATE INDEX idx_audit_events_app_time ON audit_events(app_id,occurred_at);
